#!/usr/bin/env sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Generated by build.py from recipe.yml for recipe http-expire-a-token-mid-session. Do not edit.
set -e
cd "$(dirname "$0")"
printf '%s\n' 'control-token-0123456789abcdefghij' > control-token.txt
printf '%s' 'tok-from-yesterday' > stale-token.txt
printf '%s' '{"user":"","password":"tok-2"}' > bearer.json
cat > client.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# The client: calls the API with the token it keeps in a file. With no token, it logs in for
# one; when the call is answered 401, it logs in again for a new token and retries once.
# Usage: sh client.sh <base URL> <user:password> <token file>
base=$1
user=$2
cache=$3

login() {
  answer=$(curl -sSf --cacert server.pem -u "$user" "${base}token?service=surl") || exit $?
  old=$(cat "$cache" 2>/dev/null)
  printf '%s' "$answer" | sed 's/^{"token":"\([^"]*\)".*/\1/' > "$cache"
  if [ -z "$old" ]; then echo "login: token issued"
  elif [ "$old" = "$(cat "$cache")" ]; then echo "login: same token"
  else echo "login: new token"; fi
}

call() {
  curl -s --cacert server.pem --oauth2-bearer "$(cat "$cache")" -o api.out -w "%{http_code}" "${base}v2/"
}

test -s "$cache" || login
status=$(call)
echo "call: $status"
if [ "$status" = 401 ]; then
  login
  status=$(call)
  echo "retry: $status"
fi
test "$status" = 200
EOF
cat > logins.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Polls the control endpoint, at most 25 times 0.2 s apart, until it holds at least <count>
# judged logins, then prints one line per login: account, mechanism, accepted or refused.
# Usage: sh logins.sh <control URL> <count>
auth="Authorization: Bearer $(head -n 1 control-token.txt)"
tries=0
while :; do
  events=$(curl -s -H "$auth" "$1/v1/events?kind=login_judged")
  count=$(printf '%s' "$events" | grep -o '"kind":"login_judged"' | wc -l | tr -d ' ')
  [ "$count" -ge "$2" ] && break
  tries=$((tries + 1))
  [ "$tries" -ge 25 ] && break
  sleep 0.2
done
printf '%s' "$events" | grep -o '"account":"[^"]*","mechanism":"[^"]*","is_accepted":[a-z]*' \
  | sed -e 's/"account":"\([^"]*\)","mechanism":"\([^"]*\)","is_accepted":/\1 \2 /' -e 's/ true$/ accepted/' -e 's/ false$/ refused/'
EOF
openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"
surl --cert server.pem --key server.key --user app:s3cret --control http://127.0.0.1:8081 --control-token-file control-token.txt oci://127.0.0.1:8080/ &
sleep 1
sh client.sh https://127.0.0.1:8080/ app:s3cret token.txt && curl -s -o /dev/null -w "reset: %{response_code}\n" -X POST -H "Authorization: Bearer control-token-0123456789abcdefghij" http://127.0.0.1:8081/v1/reset && sh client.sh https://127.0.0.1:8080/ app:s3cret token.txt
kill $(jobs -p)
